import sys

class AntiPalindrome:
    def execute(self, reader, writer):
        N = int(reader.readline())
        letterCount = [0] * 26
        totalMoves = 0
        line = reader.readline().strip()
        s = list(line)
        costStrs = reader.readline().split()
        costs = list(map(int, costStrs))
        totalCost = sum(costs)
        for i in range(N // 2):
            if s[i] == s[N - i - 1]:
                letterCount[ord(s[i]) - ord('a')] += 1
                totalMoves += 1
                totalCost -= min(costs[i], costs[N - i - 1])
        for c in range(26):
            if letterCount[c] > totalMoves / 2:
                excess = letterCount[c] * 2 - totalMoves
                positions = []
                for j in range(N // 2):
                    if s[j] != s[N - j - 1]:
                        if (ord(s[j]) - ord('a') != c) and (ord(s[N - j - 1]) - ord('a') != c):
                            positions.append(min(costs[j], costs[N - j - 1]))
                positions.sort()
                for j in range(min(excess, len(positions))):
                    totalCost -= positions[j]
        writer.write(str(totalCost) + "\n")

def main():
    reader = sys.stdin
    writer = sys.stdout
    AntiPalindrome().execute(reader, writer)

if __name__ == "__main__":
    main()

